/* @lc app=leetcode id=3976 lang=kotlin */ class Solution { fun best(nums: IntArray, t: (Int) -> Long): Long = nums.fold(Triple(Long.MIN_VALUE / 4, Long.MIN_VALUE / 4, Long.MIN_VALUE / 4) to Long.MIN_VALUE / 4) { (st, ans), a -> st.let { (f0, f1, f2) -> Triple(maxOf(f0, 0L) + a, maxOf(f1, maxOf(f0, 0L)) + t(a), maxOf(f2, f1) + a).let { nt -> nt to maxOf(ans, nt.second, nt.third) } } }.second fun kad(a: List<Int>): Long = a.fold(Long.MIN_VALUE / 4 to Long.MIN_VALUE / 4) { (cur, best), x -> (maxOf(cur, 0L) + x).let { it to maxOf(best, it) } }.second fun maxSubarraySum(nums: IntArray, k: Int): Long = maxOf(best(nums) { it.toLong() * k }, best(nums) { (it / k).toLong() }, if (nums.size > 1) maxOf(kad(nums.dropLast(1)), kad(nums.drop(1))) else Long.MIN_VALUE) }